{
    c = max(c, 0);
    return float3(
      c.x <= .0031308 ? c.x * 12.92 : 1.055 * pow(c.x, 1 / 2.4) - .055,
      c.y <= .0031308 ? c.y * 12.92 : 1.055 * pow(c.y, 1 / 2.4) - .055,
      c.z <= .0031308 ? c.z * 12.92 : 1.055 * pow(c.z, 1 / 2.4) - .055);
